109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
115	        owner.setTelephone(normalizedTelephone);
116	        owner.setEmail(normalizeEmail(owner.getEmail()));
117	        owner.setAddress(normalizeAddress(owner.getAddress()));
118	        validatePostcode(owner.getCity(), owner.getPostcode());
119	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
120	        if (effectiveRegistrationDate == null) {
121	            effectiveRegistrationDate = LocalDate.now();
122	        }
123	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
124	        owner.setRegistrationDate(effectiveRegistrationDate);
125	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
126	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
127	                "the maximum number of owners that may be created today has been reached");
128	        }
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        if (sharesHousehold) {
131	            this.clinicService.assignHousehold(owner);
132	        }
133	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
134	            throw new ResponseStatusException(HttpStatus.CONFLICT,
135	                "an owner with the same identity already exists");
136	        }
137	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
138	            throw new ResponseStatusException(HttpStatus.CONFLICT,
139	                "city has reached its maximum number of owners");
140	        }
141	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
142	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
143	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
144	        owner.setBulkSignupWarning(
145	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
146	        this.clinicService.saveOwner(owner);
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
149	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
150	            ownerDto.getMembershipLevel());
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
