166	        currentOwner.setLastName(ownerFieldsDto.getLastName());
167	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
168	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
169	        this.clinicService.saveOwner(currentOwner);
170	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
